/**
 * DmInfoConfigService — Database Persistence via Clinical Office DMInfo
 *
 * Saves and loads the application configuration (custom parameter types and
 * custom service definitions) to/from the Cerner database using the Clinical
 * Office CustomService DMInfo mechanism. This allows configuration to persist
 * across browsers and workstations for the same Cerner user.
 *
 * Uses INFO_DOMAIN 'DWSV' and INFO_NAME 'APP_CONFIG' as the storage key.
 * Configuration is scoped per user via infoDomainId = prsnlId.
 */
import { Injectable, inject, signal } from '@angular/core';
import { MPageService, CustomService } from '@clinicaloffice/mpage-developer';
import { UserConfigBundle } from '../models/user-config.model';

const INFO_DOMAIN = 'DWSV';
const INFO_NAME = 'APP_CONFIG';
const TIMEOUT_MS = 5000;

@Injectable({ providedIn: 'root' })
export class DmInfoConfigService {
  private customService = inject(CustomService);
  private mPage = inject(MPageService);

  readonly saving = signal(false);
  readonly loading = signal(false);

  /**
   * Save the provided configuration bundle to the Cerner database via DMInfo,
   * scoped to the given prsnlId.
   */
  async saveToDatabase(prsnlId: number, bundle: UserConfigBundle): Promise<{ success: boolean; message: string }> {
    this.saving.set(true);

    try {
      const dmInfo = this.customService.emptyDmInfo;
      dmInfo.infoDomain = INFO_DOMAIN;
      dmInfo.infoName = INFO_NAME;
      dmInfo.infoDomainId = prsnlId;
      dmInfo.infoLongText = JSON.stringify(bundle);

      const result = await new Promise<{ success: boolean; message: string }>((resolve, reject) => {
        const timer = setTimeout(
          () => reject(new Error(`Save timed out after ${TIMEOUT_MS / 1000} seconds`)),
          TIMEOUT_MS
        );

        try {
          this.customService.executeDmInfoAction('dwsv_save', 'w', [dmInfo], () => {
            clearTimeout(timer);
            resolve({ success: true, message: 'Configuration saved to database' });
          });
        } catch (err: any) {
          clearTimeout(timer);
          reject(new Error(`DMInfo save failed: ${err.message}`));
        }
      });

      this.mPage.putLog('DmInfoConfigService: Configuration saved to database');
      return result;

    } catch (err: any) {
      this.mPage.putLog(`DmInfoConfigService: Save failed - ${err.message}`);
      throw err;
    } finally {
      this.saving.set(false);
    }
  }

  /**
   * Load configuration from the Cerner database via DMInfo for the given
   * prsnlId and return the raw bundle without importing into any services.
   */
  async loadFromDatabase(prsnlId: number): Promise<{ success: boolean; message: string; bundle?: UserConfigBundle }> {
    this.loading.set(true);

    try {
      const dmInfo = this.customService.emptyDmInfo;
      dmInfo.infoDomain = INFO_DOMAIN;
      dmInfo.infoName = INFO_NAME;
      dmInfo.infoDomainId = prsnlId;

      const result = await new Promise<{ success: boolean; message: string; bundle?: UserConfigBundle }>(
        (resolve, reject) => {
          const timer = setTimeout(
            () => reject(new Error(`Load timed out after ${TIMEOUT_MS / 1000} seconds`)),
            TIMEOUT_MS
          );

          try {
            this.customService.executeDmInfoAction('dwsv_load', 'r', [dmInfo], () => {
              clearTimeout(timer);

              try {
                const response = this.customService.get('dwsv_load');
                const longText = response?.dmInfo?.[0]?.longText
                  ?? response?.longText
                  ?? response?.infoLongText;

                if (!longText) {
                  resolve({ success: true, message: 'No saved configuration found' });
                  return;
                }

                const bundle: UserConfigBundle = JSON.parse(longText);
                resolve({
                  success: true,
                  message: 'Configuration loaded from database',
                  bundle
                });
              } catch (err: any) {
                reject(new Error(`Failed to parse database configuration: ${err.message}`));
              }
            });
          } catch (err: any) {
            clearTimeout(timer);
            reject(new Error(`DMInfo load failed: ${err.message}`));
          }
        }
      );

      this.mPage.putLog(`DmInfoConfigService: ${result.message}`);
      return result;

    } catch (err: any) {
      this.mPage.putLog(`DmInfoConfigService: Load failed - ${err.message}`);
      throw err;
    } finally {
      this.loading.set(false);
    }
  }
}
